//── Tile lookup ──────────────────────────────────
// Returns palette index (0=empty) at (layer, tx, ty).
//
// Usage in renderer:
//   uint8_t pal = at_layer_tile(layer, x, y);
//   if (!pal) continue;
//   uint8_t img = kPalImage[pal];  // → ImageIndex for ext_img_slots
//   uint8_t flg = kPalFlags[pal];  // → bit0=H, bit1=V, bit2=D
//   draw_external_image(img, x*256, y*256, 256, 256, flg);
inline uint8_t at_layer_tile(uint32_t layer, int tx, int ty) {
    if (layer >= kLayerCount || tx < 0 || tx >= (int)kGridW || ty < 0 || ty >= (int)kGridH)
        return 0;
    return kLayerData[layer][ty * kGridW + tx];
}

